2297	export class ChartOp extends Operator<ChartOp> {
2298	  static displayName = 'Chart'
2299	  static description = 'Create charts using Observable Plot (bar, histogram, scatter)'
2300	
2301	  createInputs() {
2302	    const data = new DataField()
2303	    const chartType = new StringLiteralField('bar', { values: ['bar', 'histogram', 'scatter'] })
2304	    const xField = new StringLiteralField('', [])
2305	    const yField = new StringLiteralField('', [])
2306	
2307	    // Dynamic field population pattern (from FilterOp)
2308	    data.subscribe((data: unknown[]) => {
2309	      if (Array.isArray(data) && data.length > 0) {
2310	        const keys = Object.keys(data[0])
2311	        xField.updateChoices(keys)
2312	        yField.updateChoices(keys)
2313	      }
2314	    })
2315	
2316	    // Field visibility based on chart type
2317	    chartType.subscribe(type => {
