    // Dynamic field population pattern (from FilterOp)
    data.subscribe((data: unknown[]) => {
      if (Array.isArray(data) && data.length > 0) {
        const keys = Object.keys(data[0])
        xField.updateChoices(keys)
        yField.updateChoices(keys)
      }
    })

